scripts.args_schema:
{
  "type": "object",
  "properties": {
    "keyword": {
      "type": "string",
      "description": "兼容单组知网主题检索词；推荐使用 keywords"
    },
    "keywords": {
      "type": "array",
      "items": { "type": "string", "minLength": 1, "maxLength": 200 },
      "minItems": 1,
      "maxItems": 6,
      "description": "一到六组知网主题检索词；逐组检索、合并去重，并在请求预算内导出 GB/T 7714 引文"
    },
    "page": {
      "type": "integer",
      "minimum": 1,
      "description": "页码，默认 1"
    }
  },
  "anyOf": [
    { "required": ["keyword"] },
    { "required": ["keywords"] }
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "filename": {
      "type": "string",
      "description": "知网搜索结果中该文献的 CookieName 标识"
    }
  },
  "required": [
    "filename"
  ],
  "additionalProperties": false
}
